<html lang="ar" dir="rtl">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>طبقات الأرض الجيولوجية · القشرة والوشاح والنواة</title>
<style>
  :root {
    --bg: #0b1020;
    --panel: #141c33;
    --panel-2: #1b2544;
    --ink: #eef2fb;
    --muted: #9fb0d0;
    --accent: #6ea8ff;
    --crust: #8a5a2b;
    --crust-light: #c98f4e;
    --mantle: #d1542a;
    --mantle-light: #f08a3e;
    --outer: #f2b134;
    --inner: #ffe08a;
    --border: #2a3a5e;
    --shadow: 0 6px 24px rgba(0, 0, 0, 0.45);
  }

  * { box-sizing: border-box; margin: 0; padding: 0; }
  html { scroll-behavior: smooth; }

  body {
    font-family: "Segoe UI", "Noto Sans Arabic", "Amiri", "Geeza Pro",
                 "Niloofar", Tahoma, system-ui, sans-serif;
    background: var(--bg);
    color: var(--ink);
    line-height: 1.9;
    min-height: 100vh;
  }

  /* ---------- Hero ---------- */
  .hero {
    position: relative;
    text-align: center;
    padding: 72px 24px 40px;
    overflow: hidden;
  }
  .hero::before {
    content: "";
    position: absolute;
    inset: 0;
    z-index: 0;
    background:
      radial-gradient(1200px 500px at 50% -10%, rgba(110,168,255,0.22), transparent 70%),
      radial-gradient(1px 1px at 12% 22%, #fff 55%, transparent 56%),
      radial-gradient(1.4px 1.4px at 28% 12%, #cfe0ff 55%, transparent 56%),
      radial-gradient(1px 1px at 41% 30%, #fff 55%, transparent 56%),
      radial-gradient(1.6px 1.6px at 58% 15%, #fff 55%, transparent 56%),
      radial-gradient(1px 1px at 71% 26%, #cfe0ff 55%, transparent 56%),
      radial-gradient(1.3px 1.3px at 84% 18%, #fff 55%, transparent 56%),
      radial-gradient(1px 1px at 93% 34%, #fff 55%, transparent 56%);
  }
  .hero > * { position: relative; z-index: 1; }
  .hero h1 {
    font-size: clamp(1.9rem, 4.5vw, 3rem);
    color: var(--accent);
    letter-spacing: 0;
  }
  .hero .sub {
    color: var(--muted);
    margin-top: 10px;
    max-width: 640px;
    margin-inline: auto;
    font-size: 1.02rem;
  }
  .hero .badge-row {
    display: flex;
    justify-content: center;
    gap: 10px;
    flex-wrap: wrap;
    margin-top: 22px;
  }
  .badge {
    background: var(--panel);
    border: 1px solid var(--border);
    border-radius: 999px;
    padding: 5px 16px;
    font-size: 0.82rem;
    color: var(--muted);
  }
  .badge b { color: var(--ink); font-weight: 600; }

  /* ---------- Nav ---------- */
  nav.chips {
    display: flex;
    justify-content: center;
    gap: 10px;
    flex-wrap: wrap;
    padding: 8px 16px 40px;
  }
  .chip {
    font: inherit;
    font-size: 0.9rem;
    padding: 8px 20px;
    border-radius: 999px;
    border: 1px solid var(--border);
    background: var(--panel);
    color: var(--ink);
    cursor: pointer;
    transition: transform 0.15s ease, border-color 0.2s ease, box-shadow 0.2s ease;
  }
  .chip:hover { transform: translateY(-2px); box-shadow: var(--shadow); }
  .chip.active { border-color: var(--accent); box-shadow: 0 0 0 3px rgba(110,168,255,0.25); }

  main {
    max-width: 1100px;
    margin: 0 auto;
    padding: 0 20px 80px;
  }

  /* ---------- Cross-section diagram ---------- */
  .diagram-section {
    background: var(--panel);
    border: 1px solid var(--border);
    border-radius: 18px;
    box-shadow: var(--shadow);
    padding: 28px;
    margin-bottom: 48px;
  }
  .diagram-section h2 {
    text-align: center;
    color: var(--accent);
    font-size: 1.5rem;
    margin-bottom: 6px;
  }
  .diagram-section .hint {
    text-align: center;
    color: var(--muted);
    font-size: 0.9rem;
    margin-bottom: 18px;
  }
  .diagram-wrap {
    display: grid;
    grid-template-columns: minmax(280px, 460px) 1fr;
    gap: 28px;
    align-items: center;
  }
  @media (max-width: 820px) {
    .diagram-wrap { grid-template-columns: 1fr; }
    .diagram-svg { margin: 0 auto; }
  }
  .diagram-svg { width: 100%; max-width: 460px; margin-inline: auto; }

  .layer-shape { cursor: pointer; transition: opacity 0.25s ease, filter 0.25s ease; }
  .layer-shape:hover { filter: brightness(1.15); }
  .diagram-dim .layer-shape { opacity: 0.35; }
  .diagram-dim .layer-shape.hl { opacity: 1; filter: brightness(1.2); }

  .callout {
    border-inline-start: 4px solid var(--accent);
    background: var(--panel-2);
    border-radius: 12px;
    padding: 18px 20px;
    min-height: 220px;
    transition: background 0.3s ease, border-color 0.3s ease;
  }
  .callout h3 { font-size: 1.15rem; margin-bottom: 8px; }
  .callout .depth-tag {
    display: inline-block;
    font-size: 0.78rem;
    background: rgba(110,168,255,0.15);
    color: var(--accent);
    border-radius: 6px;
    padding: 2px 10px;
    margin-bottom: 10px;
  }
  .callout p { color: var(--muted); font-size: 0.95rem; }
  .callout p strong { color: var(--ink); }

  /* ---------- Layer sections ---------- */
  section.layer {
    background: var(--panel);
    border: 1px solid var(--border);
    border-radius: 18px;
    box-shadow: var(--shadow);
    margin-bottom: 44px;
    overflow: hidden;
    scroll-margin-top: 20px;
  }
  .layer-head {
    display: flex;
    align-items: center;
    gap: 16px;
    padding: 22px 28px;
    border-bottom: 1px solid var(--border);
  }
  .swatch {
    width: 52px;
    height: 52px;
    border-radius: 12px;
    flex: 0 0 auto;
    box-shadow: inset 0 0 0 3px rgba(255,255,255,0.15);
  }
  .swatch.crust { background: linear-gradient(135deg, var(--crust-light), var(--crust)); }
  .swatch.mantle { background: linear-gradient(135deg, var(--mantle-light), var(--mantle)); }
  .swatch.core   { background: linear-gradient(135deg, var(--inner), var(--outer)); }
  .layer-head h2 { font-size: 1.35rem; }
  .layer-head .depth {
    margin-inline-start: auto;
    color: var(--muted);
    font-size: 0.85rem;
    text-align: end;
    white-space: nowrap;
  }

  .layer-body { padding: 26px 28px; }
  .layer-body p { margin-bottom: 1em; color: #cdd8ec; }
  .layer-body p:last-child { margin-bottom: 0; }

  .facts {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
    gap: 14px;
    margin: 20px 0;
  }
  .fact {
    background: var(--panel-2);
    border: 1px solid var(--border);
    border-radius: 12px;
    padding: 14px 16px;
    text-align: center;
  }
  .fact .num {
    font-size: 1.35rem;
    font-weight: 700;
    color: var(--accent);
  }
  .fact .lbl {
    font-size: 0.8rem;
    color: var(--muted);
    margin-top: 4px;
  }

  .sublayers {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 14px;
    margin-top: 18px;
  }
  @media (max-width: 700px) { .sublayers { grid-template-columns: 1fr; } }
  .sublayer {
    border: 1px dashed var(--border);
    border-radius: 12px;
    padding: 14px 18px;
    font-size: 0.92rem;
    color: #cdd8ec;
  }
  .sublayer h4 {
    color: var(--ink);
    margin-bottom: 6px;
    font-size: 1rem;
  }
  .sublayer .en {
    color: var(--muted);
    font-size: 0.78rem;
    display: block;
    margin-bottom: 6px;
    direction: ltr;
    text-align: end;
  }

  /* ---------- Depth bar ---------- */
  .depth-section {
    background: var(--panel);
    border: 1px solid var(--border);
    border-radius: 18px;
    box-shadow: var(--shadow);
    padding: 28px;
    margin-bottom: 44px;
  }
  .depth-section h2 {
    text-align: center;
    color: var(--accent);
    font-size: 1.5rem;
    margin-bottom: 20px;
  }
  .depth-bar {
    position: relative;
    height: 74px;
    border-radius: 12px;
    overflow: hidden;
    border: 1px solid var(--border);
    display: flex;
  }
  .db-seg {
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    color: #fff;
    font-size: 0.82rem;
    font-weight: 600;
    min-width: 40px;
    text-align: center;
    padding: 4px;
  }
  .db-seg small { font-weight: 400; opacity: 0.85; font-size: 0.7rem; }
  .db-crust { background: var(--crust); width: 4%; }
  .db-mantle { background: linear-gradient(90deg, var(--mantle), #a03a1e); flex: 1; }
  .db-outer { background: var(--outer); width: 22%; color: #4a3305; }
  .db-outer small { color: #4a3305; }
  .db-inner { background: var(--inner); width: 12%; color: #5b430a; }
  .db-inner small { color: #5b430a; }
  @media (max-width: 600px) {
    .db-seg small { display: none; }
    .db-crust { font-size: 0.6rem; }
  }
  .depth-legend {
    display: flex;
    justify-content: space-between;
    color: var(--muted);
    font-size: 0.78rem;
    margin-top: 10px;
    direction: ltr;
  }

  /* ---------- Quiz ---------- */
  .quiz {
    background: var(--panel);
    border: 1px solid var(--border);
    border-radius: 18px;
    box-shadow: var(--shadow);
    padding: 28px;
  }
  .quiz h2 { color: var(--accent); font-size: 1.4rem; margin-bottom: 16px; text-align: center; }
  .q { margin-bottom: 22px; }
  .q p { margin-bottom: 10px; color: #cdd8ec; }
  .q .opts { display: flex; flex-direction: column; gap: 8px; }
  .opt {
    font: inherit;
    font-size: 0.92rem;
    text-align: start;
    padding: 10px 16px;
    border-radius: 10px;
    border: 1px solid var(--border);
    background: var(--panel-2);
    color: var(--ink);
    cursor: pointer;
    transition: border-color 0.2s ease, background 0.2s ease;
  }
  .opt:hover { border-color: var(--accent); }
  .opt.correct { border-color: #4caf7d; background: rgba(76,175,125,0.18); }
  .opt.wrong { border-color: #e05555; background: rgba(224,85,85,0.15); }
  .q .feedback { font-size: 0.85rem; color: var(--muted); margin-top: 8px; min-height: 1.2em; }

  footer {
    text-align: center;
    color: var(--muted);
    font-size: 0.8rem;
    padding: 0 20px 44px;
  }
</style>
</head>
