    }
  };

  var callout = document.getElementById('callout');
  var tTitle = document.getElementById('calloutTitle');
  var tDepth = document.getElementById('calloutDepth');
  var tText = document.getElementById('calloutText');
  var svg = document.querySelector('.diagram-svg');

  function showLayer(key) {
    var info = INFO[key];
    if (!info) return;
    svg.classList.add('diagram-dim');
    document.querySelectorAll('.layer-shape').forEach(function (el) {
      el.classList.toggle('hl', el.dataset.layer === key);
    });
    tTitle.textContent = info.title;
    tDepth.textContent = info.depth;
    tText.innerHTML = info.text;
  }

  document.querySelectorAll('.layer-shape').forEach(function (el) {
    el.addEventListener('mouseenter', function () { showLayer(el.dataset.layer); });
    el.addEventListener('click', function () { showLayer(el.dataset.layer); });
  });
  svg.addEventListener('mouseleave', function () {
    svg.classList.remove('diagram-dim');
    document.querySelectorAll('.layer-shape.hl').forEach(function (el) {
      el.classList.remove('hl');
    });
  });

  /* ---------- أزرار التنقل مع تمييز تلقائي حسب التمرير ---------- */
  var chips = Array.prototype.slice.call(document.querySelectorAll('.chip'));
  var targets = chips
    .map(function (c) { return document.getElementById(c.dataset.target); })
    .filter(Boolean);

  function markActive(id) {
    chips.forEach(function (c) {
      c.classList.toggle('active', c.dataset.target === id);
    });
  }

  chips.forEach(function (chip) {
    chip.addEventListener('click', function () {
      var el = document.getElementById(chip.dataset.target);
      if (!el) return;
      el.scrollIntoView({ behavior: 'smooth', block: 'start' });
      markActive(chip.dataset.target);
    });
  });

  var ticking = false;
  window.addEventListener('scroll', function () {
    if (ticking) return;
    ticking = true;
    requestAnimationFrame(function () {
      var mid = window.scrollY + window.innerHeight / 2;
      var current = null;
      targets.forEach(function (s) {
        if (s.offsetTop <= mid && mid < s.offsetTop + s.offsetHeight) current = s.id;
      });
      if (current) markActive(current);
      ticking = false;
    });
  }, { passive: true });

  /* ---------- الاختبار ---------- */
  document.querySelectorAll('.q').forEach(function (q) {
    var answer = q.dataset.answer;
    var feedback = q.querySelector('.feedback');
    q.querySelectorAll('.opt').forEach(function (opt) {
      opt.addEventListener('click', function () {
        q.querySelectorAll('.opt').forEach(function (o) {
          o.classList.remove('correct', 'wrong');
        });
        if (opt.dataset.key === answer) {
          opt.classList.add('correct');
          feedback.textContent = '✅ إجابة صحيحة! أحسنت.';
        } else {
          opt.classList.add('wrong');
          feedback.textContent = '❌ ليست كذلك — حاول مرة أخرى.';
        }
      });
    });
  });
})();
</script>

