def find_comments(src):
    spans, i, n = [], 0, len(src)
    while i < n:
        c = src[i]
        if c == '"' or c == "'":
            q = c; i += 1
            while i < n and src[i] != q:
                if src[i] == '\\': i += 1
                i += 1
            i += 1
        elif c == '/' and i + 1 < n and src[i+1] == '/':
            j = src.find('\n', i); j = n if j == -1 else j
            spans.append((i, j)); i = j
        elif c == '/' and i + 1 < n and src[i+1] == '*':
            depth, j = 1, i + 2
            while j < n and depth:
                if src.startswith('/*', j): depth += 1; j += 2
                elif src.startswith('*/', j): depth -= 1; j += 2
                else: j += 1
            spans.append((i, j)); i = j
        else:
            i += 1
    return spans

def strip_in_place(src):
    spans = find_comments(src)
    deleted = bytearray(len(src))
    for s, e in spans:
        deleted[s:e] = b'\x01' * (e - s)
    return ''.join(ch for k, ch in enumerate(src) if not deleted[k])

def norm(src):
    return [ln.rstrip() for ln in src.splitlines() if ln.strip()]

head = subprocess.run(['git', 'show', 'HEAD:source.kt'], capture_output=True, text=True, check=True).stdout
H = norm(strip_in_place(head))
C = norm(open('source.kt').read())

assert H == C, "MISMATCH:\nH-only: %r\nC-only: %r" % (
    [x for x in H if x not in C][:5], [x for x in C if x not in H][:5])
print(f"VERIFIED: current file == HEAD with all comments removed, {len(H)} code lines identical")
EOF
