{"command": "cd /home/agent/workspace && python3 - <<'EOF'
import subprocess, difflib

head = subprocess.run(['git', 'show', 'HEAD:source.kt'], capture_output=True, text=True, check=True).stdout.splitlines()
cur = open('source.kt').read().splitlines(keepends=True)
cur_noeol = [ln.rstrip('\n') for ln in cur]

sm = difflib.SequenceMatcher(a=head, b=cur_noeol, autojunk=False)
changed = set()
for tag, i1, i2, j1, j2 in sm.get_opcodes():
    if tag in ('replace', 'insert'):
        for j in range(j1, j2):
            changed.add(j)

fixed = 0
for j in sorted(changed):
    if cur_noeol[j] != cur_noeol[j].rstrip():
        cur[j] = cur_noeol[j].rstrip() + '\n'
        fixed += 1

open('source.kt', 'w').writelines(cur)
print(f"rstrip'd {fixed} touched lines; total changed/inserted lines: {len(changed)}")
EOF
